public class UndoRedoHistoryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            UndoRedoHistory history = new UndoRedoHistory();
            history.apply("type a");
            history.apply("type b");
            history.apply("type c");
            check("state is oldest first", "[type a, type b, type c]", history.currentState().toString());
            check("undo returns the newest action", "type c", history.undo());
            check("state after undo", "[type a, type b]", history.currentState().toString());
            check("one action waiting to redo", 1, history.redoCount());
            check("redo returns it back", "type c", history.redo());
            check("state after redo", "[type a, type b, type c]", history.currentState().toString());
            check("redo stack is empty again", 0, history.redoCount());
            history.undo();
            history.undo();
            history.apply("type d");
            check("a new action clears the redo stack", 0, history.redoCount());
            check("state after branching", "[type a, type d]", history.currentState().toString());
            check("redo with nothing undone", null, history.redo());
            UndoRedoHistory fresh = new UndoRedoHistory();
            check("undo on an empty history", null, fresh.undo());
            check("empty history state", "[]", fresh.currentState().toString());
        } catch (Throwable t) {
            broke("UndoRedoHistory", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

