import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

public class UndoRedoHistory {

    private final Deque<String> done = new ArrayDeque<>();
    private final Deque<String> undone = new ArrayDeque<>();

    public void apply(String action) {
        done.push(action);
        undone.clear();
    }

    public String undo() {
        if (done.isEmpty()) {
            return null;
        }
        String action = done.pop();
        undone.push(action);
        return action;
    }

    public String redo() {
        if (undone.isEmpty()) {
            return null;
        }
        String action = undone.pop();
        done.push(action);
        return action;
    }

    public List<String> currentState() {
        List<String> state = new ArrayList<>(done);
        Collections.reverse(state);
        return state;
    }

    public int redoCount() {
        return undone.size();
    }
}
